<?php declare(strict_types=1);namespace StudPulse\Bars;use DOMElement;use DOMNode;use DOMXPath;use StudPulse\Http\ApiError;use StudPulse\Security\Auth;final class BarsSections{private const GROUPS=['Учёба'=>['profile'=>['Профиль студента','Профиль пользователя'],'grades'=>['Оценки БАРС','Оценки в БАРС'],'summary'=>['Сводка','Сводка по оценкам БАРС и пропускам'],'statements'=>['Ведомости','Ведомости в БАРС'],'attendance'=>['Посещение занятий','Пропуски занятий','Посещения занятий','Посещаемость','Журнал посещения занятий','Пропуски'],'assignments'=>['Задания','Перечень заданий'],'reports'=>['Отчёты','Отчеты','Отчёты по КП/КР и практикам'],'attestations'=>['Аттестации','Индивидуальные аттестации'],'gia'=>['ГИА','Государственная итоговая аттестация'],'diploma'=>['Диплом'],'record-book'=>['Зачётная книжка','Зачётная книжка (ЭЗК)','Зачетная книжка (ЭЗК)','ЭЗК'],],'Рейтинг'=>['rating-study'=>['Учебный рейтинг','Учебный'],'rating-research'=>['Научно-инновационный рейтинг','Научно-инновационный'],'rating-public'=>['Общественный рейтинг','Общественный'],'rating-culture'=>['Культурно-творческий рейтинг','Культурно-творческий'],'rating-sports'=>['Спортивный рейтинг','Спортивный'],'rating-discipline'=>['Дисциплинарный рейтинг','Дисциплинарный'],'rating-calculation'=>['Расчёт рейтинга','Расчёт','Расчет'],],'События'=>['events'=>['События','Мероприятия'],'orders'=>['Приказы','Приказы и прочие документы'],'scholarships'=>['Стипендии'],'thanks'=>['Благодарности'],'additional'=>['Допобразование','Дополнительное образование'],'surveys'=>['Анкетирование','Анкеты'],],];private const EXTRA_MENU_LABELS=['Учёба','Рейтинг','ЛК, портал МЭИ','Карьера','Обучения','Портфолио','Жизненный цикл','Мои книги','Обходные листы','Записи на приём','Регистрация','Просмотр','Главная','Студенты','Выбор действия','Архив','Резюме','Подписание','Документы','Документооборот','Документы и события','График приёма','Графики приёма',];public static function catalog(array$links):array{$items=[];foreach(self::GROUPS as$group=>$sections){foreach($sections as$id=>$labels){$items[]=['id'=>$id,'title'=>$labels[0],'group'=>$group,'available'=>in_array($id,['profile','grades','events'],true)||isset($links[$id])||($id==='attendance'&&isset($links['summary'])),];}}return$items;}public static function authorize(Auth$auth,string$id):void{if(!in_array($id,array_column(self::catalog([]),'id'),true)){throw new ApiError(404,'BARS_SECTION_UNKNOWN','Такой вкладки БАРС нет.');}if(in_array($id,['grades','summary','statements','record-book'],true)||str_starts_with($id,'rating-')){$auth->require('grades:read');}if(in_array($id,['attendance','summary'],true)){$auth->require('attendance:read');}if($id==='assignments'){$auth->require('homework:read');}}public static function links(DOMXPath$xpath,string$studentId):array{$aliases=[];foreach(self::GROUPS as$sections){foreach($sections as$id=>$labels){foreach($labels as$label){$aliases[self::label($label)]=$id;}}}$links=[];foreach($xpath->query('//a[@href] | //*[@data-href or @data-url or @data-ajax-url]')as$anchor){$label=self::label(BarsHtml::text($anchor)?:$anchor->getAttribute('title'));$id=$aliases[$label]??null;$method=strtolower($anchor->getAttribute('data-ajax-method')?:'get');if($id===null||isset($links[$id])||$method!=='get'){continue;}foreach(['href','data-href','data-url','data-ajax-url']as$attribute){$path=self::path($anchor->getAttribute($attribute),$studentId);if($path!==null){$links[$id]=$path;break;}}}return$links;}private static function label(string$text):string{return str_replace('ё','е',mb_strtolower(trim(preg_replace('/[\s\p{Z}]+/u',' ',$text))));}public static function path(string$href,string$studentId):?string{if($href===''||strlen($href)>1500||preg_match('/[\x00-\x20\\\\]/',$href)){return null;}$parts=parse_url($href);if($parts===false||isset($parts['user'])||isset($parts['pass'])||(isset($parts['scheme'])&&strtolower($parts['scheme'])!=='https')){return null;}if((isset($parts['host'])&&strtolower($parts['host'])!=='bars.mpei.ru')||(isset($parts['port'])&&$parts['port']!==443)){return null;}$path='/'.ltrim($parts['path']??'','/');if(preg_match('~^/ST(?:_[A-Za-z0-9_]+)?/~i',$path)){$path='/bars_web'.$path;}if(!preg_match('~^/bars_web/ST(?:_[A-Za-z0-9_]+)?(?:/[A-Za-z0-9_-]+)+/?$~iD',$path)){return null;}if(preg_match('~/(?:JSON_[A-Za-z0-9_]+|delete|remove|create|add|edit|save|submit|upload|approve|confirm|update|logout|sign)(?:/|$)~i',$path)){return null;}$query=$parts['query']??'';parse_str($query,$params);$lower=array_change_key_case($params,CASE_LOWER);if(count($lower)!==count($params)||!is_string($lower['studentid']??null)||!hash_equals($studentId,$lower['studentid'])){return null;}foreach($params as$key=>$value){if(!is_string($value)||preg_match('/^(?:action|command|method|userid|personid|employeeid|groupid)$/iD',$key)){return null;}}return$path.'?'.http_build_query($params,'','&',PHP_QUERY_RFC3986);}public static function blocks(DOMXPath$xpath):array{$main=$xpath->query('//main | //*[@role="main"] | //*[@id="mainContent"] | //div[contains(concat(" ",normalize-space(@class)," ")," body-content ")]')->item(0);$root=$main??$xpath->query('//body')->item(0);if(!$root){return[];}$blocks=[];$seen=[];$menuPattern=self::menuPattern();$nodes=$xpath->query('.//*[self::table or self::h1 or self::h2 or self::h3 or self::h4 or self::p or self::li or self::dt or self::dd or (self::div and not(*))][not(ancestor::table or ancestor::nav or ancestor::header or ancestor::footer or ancestor::script or ancestor::style or ancestor::template)]',$root);foreach($nodes as$node){if(self::hidden($node)){continue;}if($node->nodeName==='table'){$rows=self::rows($xpath,$node);if($rows){$blocks[]=['kind'=>'table','rows'=>$rows];}continue;}$text=self::text($node);if($text!==''&&!isset($seen[$text])&&!preg_match($menuPattern,self::label($text))){$seen[$text]=true;$blocks[]=['kind'=>preg_match('/^h[1-4]$/',$node->nodeName)?'heading':'text','text'=>$text];}}return$blocks;}private static function menuPattern():string{$labels=self::EXTRA_MENU_LABELS;foreach(self::GROUPS as$sections){foreach($sections as$aliases){array_push($labels,...$aliases);}}usort($labels,static fn(string$a,string$b):int=>strlen($b)<=>strlen($a));$alternatives=array_map(static fn(string$text):string=>preg_quote(self::label($text),'~'),$labels);return'~^(?:\s*(?>'.implode('|',$alternatives).'))+\s*$~uD';}public static function attendanceBlocks(array$blocks):array{return array_values(array_filter($blocks,static function(array$block):bool{if($block['kind']!=='table'){return false;}$rows=array_map(static fn(array$row):array=>array_column($row,'text'),$block['rows']);if(BarsStatistics::attendanceSummaryColumns($rows)!==null){return true;}$headers='';foreach(array_slice($rows,0,8)as$row){$headers.=' '.implode(' ',$row);}$headers=self::label($headers);return mb_stripos($headers,'пропущено')!==false&&mb_stripos($headers,'занятий')!==false&&mb_stripos($headers,'уважительной причине')!==false;}));}private static function rows(DOMXPath$xpath,DOMElement$table):array{$rows=[];foreach($xpath->query('./thead/tr | ./tbody/tr | ./tfoot/tr | ./tr',$table)as$row){if(self::hidden($row)){continue;}$cells=[];foreach($xpath->query('./th | ./td',$row)as$cell){if(!self::hidden($cell)){$text=self::text($cell);if($text===''){foreach($xpath->query('.//*[@title or @aria-label or @alt]',$cell)as$marker){$hint=trim($marker->getAttribute('aria-label')?:$marker->getAttribute('title')?:$marker->getAttribute('alt'));if(!self::hidden($marker)&&preg_match('/^(?:без уп|уп|без уважительной причины|по (?:не)?уважительной причине)$/uiD',$hint)){$text=$hint;break;}}}$cells[]=['text'=>$text,'header'=>$cell->nodeName==='th'||$row->parentNode->nodeName==='thead','colspan'=>max(1,min(40,(int)$cell->getAttribute('colspan'))),'rowspan'=>max(1,min(100,(int)$cell->getAttribute('rowspan'))),];}}if($cells&&array_filter($cells,static fn(array$cell):bool=>$cell['text']!=='')){$rows[]=$cells;}}return$rows;}private static function text(DOMNode$node):string{$parts=[];foreach($node->childNodes as$child){if($child->nodeType===XML_TEXT_NODE){$parts[]=$child->nodeValue;}elseif($child instanceof DOMElement&&!in_array($child->nodeName,['script','style','select','input','button','textarea','table','svg','img'],true)&&!self::hidden($child)){$parts[]=self::text($child);}}return trim(preg_replace('/\s+/u',' ',implode(' ',$parts))??'');}private static function hidden(DOMElement$node):bool{for($element=$node;$element instanceof DOMElement;$element=$element->parentNode){if($element->hasAttribute('hidden')||strtolower($element->getAttribute('aria-hidden'))==='true'||strtolower($element->getAttribute('role'))==='navigation'||preg_match('/(?:^|\s)(?:navbar|navbar-nav|nav|nav-link|dropdown-menu|breadcrumb|pagination|d-none|hidden)(?:\s|$)/',$element->getAttribute('class'))||preg_match('/display\s*:\s*none/i',$element->getAttribute('style'))){return true;}}return false;}}